    const was = by.get(c.personId) ?? { upTo30: 0, upTo60: 0, over60: 0 };
    if (c.date >= from30) by.set(c.personId, { ...was, upTo30: was.upTo30 + due });
    else if (c.date >= from60) by.set(c.personId, { ...was, upTo60: was.upTo60 + due });
